-- Schema of `csi_db`, generated by `npm run db:schema`. Do not edit by hand.
-- Structure only: no rows. Unrelated legacy tables are excluded.

CREATE TABLE `aqlplan` (
  `planid` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `inspectlevel` varchar(10) NOT NULL,
  `aql` varchar(20) NOT NULL,
  `isdefault` tinyint(1) NOT NULL DEFAULT 0,
  `note` varchar(255) DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`planid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

CREATE TABLE `aqlplanrow` (
  `planid` int(11) NOT NULL,
  `inspectcategory` int(11) NOT NULL,
  `lotmin` int(11) NOT NULL,
  `lotmax` int(11) DEFAULT NULL,
  `codeletter` varchar(2) NOT NULL,
  `samplesize` int(11) NOT NULL,
  `acceptnum` int(11) NOT NULL,
  `rejectnum` int(11) NOT NULL,
  PRIMARY KEY (`planid`,`inspectcategory`,`lotmin`),
  CONSTRAINT `fk_aqlplanrow_plan` FOREIGN KEY (`planid`) REFERENCES `aqlplan` (`planid`) ON DELETE CASCADE,
  CONSTRAINT `chk_aqlplanrow_category` CHECK (`inspectcategory` in (1,2,3)),
  CONSTRAINT `chk_aqlplanrow_lot` CHECK (`lotmin` >= 1 and (`lotmax` is null or `lotmax` >= `lotmin`)),
  CONSTRAINT `chk_aqlplanrow_numbers` CHECK (`samplesize` >= 1 and `acceptnum` >= 0 and `rejectnum` > `acceptnum`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

CREATE TABLE `inspectline` (
  `inspectnum` varchar(30) NOT NULL,
  `linenum` int(11) NOT NULL,
  `inspecttype` varchar(50) DEFAULT NULL,
  `inspectitem` varchar(100) DEFAULT NULL,
  `standard_txt` varchar(100) DEFAULT NULL,
  `standard` decimal(18,2) DEFAULT NULL,
  `tolerance` decimal(18,2) DEFAULT 0.00,
  `tolerance_txt` varchar(50) DEFAULT NULL,
  `tolerance_plus` decimal(19,2) DEFAULT NULL,
  `tolerance_minus` decimal(19,2) DEFAULT NULL,
  `actual_1` decimal(18,2) DEFAULT NULL,
  `actual_2` decimal(18,2) DEFAULT NULL,
  `actual_3` decimal(18,2) DEFAULT NULL,
  `actual_4` decimal(18,2) DEFAULT NULL,
  `actual_5` decimal(18,2) DEFAULT NULL,
  `actual_6` decimal(18,2) DEFAULT NULL,
  `actual_7` decimal(18,2) DEFAULT NULL,
  `status_1` int(11) DEFAULT NULL,
  `status_2` int(11) DEFAULT NULL,
  `status_3` int(11) DEFAULT NULL,
  `status_4` int(11) DEFAULT NULL,
  `status_5` int(11) DEFAULT NULL,
  `status_6` int(11) DEFAULT NULL,
  `status_7` int(11) DEFAULT NULL,
  PRIMARY KEY (`inspectnum`,`linenum`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

