  `actual_txt_7` varchar(100) DEFAULT NULL,
  `status_1` int(11) DEFAULT NULL,
  `status_2` int(11) DEFAULT NULL,
  `status_3` int(11) DEFAULT NULL,
  `status_4` int(11) DEFAULT NULL,
  `status_5` int(11) DEFAULT NULL,
  `status_6` int(11) DEFAULT NULL,
  `status_7` int(11) DEFAULT NULL,
